INSERT INTO `product` (`id`, `product_name`, `slug`, `price`, `sale_price`, `categories`, `description`, `benefit`, `how_to_use`, `return_exchange`, `disclaimer`, `photo_folder`, `photo1`, `photo2`, `photo3`, `photo4`, `photo5`, `photo6`, `is_in_stock`, `product_review`, `is_ratti`, `is_active`) VALUES
(1, '1 Mukhi Rudraksha', '1-mukhi-rudraksha', 25058.00, 6999.00, '20,45', 'The 1 Mukhi Rudraksha is a sacred bead that carries divine energy and blessings. Known for its power to enhance focus, peace, and spiritual growth, this premium-quality Rudraksha supports clarity of mind and inner strength. Perfect for meditation, worship, or daily wear, it brings balance, protection, and positivity into your life.', 'Encourages deep meditation, peace, and spiritual growth. \nSupports focus, clarity, and confidence in daily life. \nHelps reduce stress, negativity, and emotional blockages. \nAttracts divine blessings, prosperity, and protection. \nBrings balance between mind, body, and soul.', 'Wear the 1 or Ek Mukhi Rudraksha close to your heart on a thread or silver/gold chain to absorb its divine vibrations. \nUse during meditation or prayers to enhance focus, peace, and connection with higher energy. \nKeep it in your worship space for continuous blessings and protection. \nCleanse occasionally with clean water and wipe gently with a soft cloth. \nRecharge by keeping it in sunlight for a few minutes or by chanting mantras near it.', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', '1-mukhi-rudraksha', '1-mukhi-rudraksha_1.jpg', '1-mukhi-rudraksha_2.jpg', '1-mukhi-rudraksha_3.jpg', '1-mukhi-rudraksha_5.jpg', '1-mukhi-rudraksha_6.jpg', '1-mukhi-rudraksha_7.jpg', 1, '4', '0', 1),
(2, '7 Chakra Rudraksha Bracelet', '7-chakra-rudraksha-bracelet', 1999.00, 799.00, '7,20', 'This auspicious 7 chakra rudraksha bracelet combines natural rudraksha beads with chakra stones to promote harmony and balance. It helps align your body’s energy, bringing peace, positivity, and focus. Stylish and comfortable, this bracelet is perfect for daily wear, supporting both spiritual growth and emotional well-being.', 'Balances seven chakras to improve energy flow and inner harmony. \nRudraksha beads support calmness, peace, and spiritual connection. \nStylish design makes it perfect for casual wear and meditation. \nHelps reduce stress while enhancing clarity and emotional stability.', 'Wear the 7 chakra rudraksha bracelet on your right hand for energy balance. \nRemove before sleeping. \nRecharge by placing it under sunlight or moonlight for a few hours regularly. \nWipe gently with a clean cloth, avoiding water to preserve the natural quality.', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', '7-chakra-rudraksha-bracelet', '7-chakra-rudraksha-bracelet_1.jpg', '7-chakra-rudraksha-bracelet_2.jpg', '7-chakra-rudraksha-bracelet_3.jpg', '7-chakra-rudraksha-bracelet_4.jpg', '7-chakra-rudraksha-bracelet_5.jpg', '7-chakra-rudraksha-bracelet_6.jpg', 1, '4.5', '0', 1),
(3, '7 Chakra Diary', '7-chakra-diary', 2499.00, 1899.00, '4', 'This premium 7 Chakra Diary is designed to help you align thoughts, emotions, and energy through mindful writing. Ideal as a unique office diary or for personal journaling, it encourages self-expression and positivity. Its elegant design makes it suitable for daily use or gifting with purpose and meaning.', 'Boosts creativity and focus by encouraging daily mindful writing habits. \nPromotes stress relief and emotional balance through daily writing practice. \nHelps track goals, intentions, and spiritual growth consistently over time. \nStylish and versatile diary suitable for personal, professional, and spiritual use.', 'Use daily to record thoughts, goals, or gratitude for improved focus and positivity. \nWrite affirmations or intentions to align with your seven chakra energies. \nKeep it handy at work or home to encourage regular mindful journaling habits. \nStore in a clean, safe space to preserve its energy and quality longer.', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', '7-chakra-diary', '7-chakra-diary_1.jpg', '7-chakra-diary_2.jpg', '7-chakra-diary_3.jpg', '7-chakra-diary_4.jpg', '7-chakra-diary_5.jpg', '7-chakra-diary_6.jpg', 1, '5', '0', 1),
(4, '7 Chakra Tree', '7-chakra-tree', 1999.00, 1399.00, '25', 'Bring harmony and positivity into your life with this 7 Chakra Tree. Designed with colorful natural crystals, it aligns your energy centers and supports spiritual well-being. A perfect blend of beauty and healing, this chakra tree also serves as an ideal gifting option for loved ones.', 'Restores energy balance across all seven chakras of the body. \nPromotes emotional healing, positivity, and overall mental clarity. \nSupports meditation, spiritual growth, and inner peace. \nEnhances home decor with vibrant, colorful natural crystals.', 'Place the 7 Chakra Tree in your living space to harmonize and balance energy flow. \nKeep it near your meditation or yoga corner to support focus and relaxation. \nCleanse occasionally with sage smoke or recharge under moonlight for renewed energy. \nGently dust with a soft cloth to preserve the crystals’ vibrant colors.', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', '7-chakra-tree', '7-chakra-tree_1.jpg', '7-chakra-tree_2.jpg', '7-chakra-tree_3.jpg', '7-chakra-tree_4.jpg', '7-chakra-tree_5.jpg', '7-chakra-tree_6.jpg', 1, '4', '0', 1),
(5, 'Amethyst Pyramid', 'amethyst-pyramid', 1999.00, 1549.00, '4', 'The Amethyst Pyramid is a powerful crystal known for its calming energy and spiritual benefits. This beautiful pyramid helps reduce stress, enhances intuition, and supports meditation practices. Placed at home, in the office, or in meditation spaces, the amethyst pyramid radiates peace and positivity, making it a thoughtful gift for loved ones.', 'This beautiful pyramid helps reduce stress, enhances intuition, and supports meditation practices. Placed at home, in the office, or in meditation spaces, the amethyst pyramid radiates peace and positivity, making it a thoughtful gift for loved ones.', 'Place the 7 Chakra Pyramid in your home, workplace, or meditation space to balance energies.\n Keep it on your work desk to enhance focus, clarity, and positive vibrations.\n Use during Reiki or healing sessions for chakra alignment and energy flow.\n Cleanse regularly with moonlight or incense to maintain its healing properties.', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'amethyst-pyramid', 'amethyst-pyramid_1.jpg', 'amethyst-pyramid_2.jpg', 'amethyst-pyramid_3.jpg', 'amethyst-pyramid_4.jpg', 'amethyst-pyramid_5.jpg', 'amethyst-pyramid_6.jpg', 1, '4.5', '0', 1),
(6, 'Annapurna Pyramid', 'annapurna-pyramid', 1999.00, 1549.00, '4,45', 'The Annapurna Pyramid is believed to attract abundance and nourishment. This sacred crystal is associated with Goddess Annapurna, symbolizing prosperity and fulfillment. Placed at home, in the kitchen, or in the dining space, it invites positivity and blessings, making it a thoughtful choice for gifting loved ones.', 'Attracts prosperity, nourishment, and blessings of Goddess Annapurna. \nCreates positive vibrations in the kitchen, dining area, or living space. \nEnhances abundance and fulfillment in personal and family life. \nActs as a powerful food pyramid crystal for daily harmony.', 'Place the Annapurna Pyramid in your kitchen to invite nourishment and prosperity.\nKeep it on a dining table to promote positivity and satisfying family dinners.\nPosition it in your home temple or altar to receive divine blessings daily.\nCleanse regularly with incense or moonlight to maintain its energy vibrations.', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'annapurna-pyramid', 'annapurna-pyramid_1.jpg', 'annapurna-pyramid_2.jpg', 'annapurna-pyramid_3.jpg', 'annapurna-pyramid_4.jpg', 'annapurna-pyramid_5.jpg', 'annapurna-pyramid_6.jpg', 1, '5', '0', 1),
(7, 'Evil Eye Car Hanging', 'evil-eye-car-hanging', 1999.00, 799.00, '19,4', 'This Evil Eye Car Hanging is made with traditional blue glass evil eye beads, designed to bring protective energy into your vehicle. Hanging it inside your car is believed to help  guard against negative energies and unwanted influences while traveling. Its simple design fits well with any car interior and adds a meaningful touch to daily commutes.\n\nWho Is This For?\n\nPeople who drive daily and want positive energy\n\nFamilies who want protection during travel\n\nCar owners who like meaningful accessories\n\nAnyone looking for a simple, symbolic car decor\n\n \n\nMaterial\n\nBlue Glass Evil Eye Beads\n\nDimension\n\nHeight: 20-22 cm, Diameter: 5-6cm\n\nBest Spot\n\nHang on the rear-view mirror\n\nCare Instruction\n\nClean gently with a dry cloth; avoid water', '', '', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'evil-eye-car-hanging', 'evil-eye-car-hanging_1.jpg', 'evil-eye-car-hanging_2.jpg', 'evil-eye-car-hanging_3.jpg', 'evil-eye-car-hanging_4.jpg', 'evil-eye-car-hanging_5.jpg', 'evil-eye-car-hanging_6.webp', 1, '5', '0', 1),
(8, '7 Mukhi Rudraksha Bracelet', '7-mukhi-rudraksha-bracelet', 1999.00, 699.00, '7,30,31,28,20', 'This 7 Mukhi Rudraksha bracelet is made with natural Rudraksha beads, each with seven separate lines. It is traditionally believed to attract wealth, emotional strength, and disciplined thinking. Wearing it daily can help you stay focused and grounded during stressful times, making it suitable for people who want calmness and better control over their thoughts.\n\nWho Is This For?\n\nPeople dealing with stress or anxiety\n\nIndividuals wanting better focus and clarity\n\nThose seeking emotional balance and calm\n\nAnyone looking for meaningful spiritual jewelry\n\n \n\nMaterial\n\nRudraksha Bead\n\nDimension\n\n10-12mm \n\nBest Spot\n\nWear on the dominant wrist\n\nCare Instruction\n\nAvoid water and perfumes; store separately', '', '', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', '7-mukhi-rudraksha-bracelet', '7-mukhi-rudraksha-bracelet_1.jpg', '7-mukhi-rudraksha-bracelet_2.jpg', '7-mukhi-rudraksha-bracelet_3.jpg', '7-mukhi-rudraksha-bracelet_4.jpg', '7-mukhi-rudraksha-bracelet_5.jpg', '7-mukhi-rudraksha-bracelet_7.jpg', 1, '5', '0', 1),
(9, 'Pyrite Tortoise (Kachhua) for Money, Protection & Vastu', 'pyrite-tortoise-kachhua-for-money-protection-and-vastu', 1299.00, 719.00, '4,28,21', 'Pyrite Tortoise is a powerful, vastu, and feng shui product made from natural Pyrite stone, a mineral found in the earth. Pyrite is often called the “money stone” because it is believed to attract wealth and positive energy. From a scientific point of view, Pyrite is known for its strong metallic energy, which is said to support focus, confidence, and mental clarity. Keeping it in your home or office may help create a balanced and motivated environment.\n\nIn traditional beliefs, the turtle represents stability, protection, and long life. When combined with Pyrite, it is thought to bring financial growth and career success. The original Pyrite Tortoise from Astrologer RaajeevG is made with authentic stone and designed as per Vastu guidelines, making it a reliable choice for those seeking positive results.\n\nWho Is This For?\n\nPeople who value authentic, premium fengshui products \n\nPeople that are looking to stabilize wealth and eliminate negative influences\n\nVastu & Feng Shui followers\n\nProfessionals, entrepreneurs, and goal-oriented individuals\n\n Ideal Placement\n\nIdeal Direction: North or North-East of your space for prosperity flow\n\nPreferred Day & Time: Thursday morning for best energy alignment\n\nIdeal Place: Home entrance shelf, office desk, cash locker area\n\nActivation Mantra: “Om Shreem Namah”', '', '', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'pyrite-tortoise-kachhua-for-money-protection-and-vastu', 'pyrite-tortoise_1.png', 'pyrite-tortoise_2.png', 'pyrite-tortoise_3.png', 'pyrite-tortoise_5.png', 'pyrite-tortoise_6.png', 'pyrite-tortoise_7.jpg', 1, '5', '0', 1),
(10, 'Dhan Yog Bracelet', 'dhan-yog-bracelet', 1999.00, 699.00, '7,28', 'This Dhan yog bracelet is super powerful because it has been designed with 6 powerful money magnet crystals, which are Citrine, Tiger Eye, Clear Quartz, Green Jade, Green Aventurine, and a Raw Pyrite. Wearing this bracelet daily supports financial focus, stability, and abundance thinking. It is a premium choice for abundance seekers.\n\nWho Is This For? \n\nAnyone working towards financial growth and long-term stability.\n\nProfessionals and business owners who are focused on success and prosperity.\n\nPeople who are seeking a positive money mindset and disciplined financial habits.\n\nAnyone looking for a thoughtful gift option with abundant meaning. \n\n \n\nMaterial\n\nCitrine, Tiger Eye, Clear Quartz, Green Jade, Green Aventurine, and a Raw Pyrite\n\nDimension\n\n22 Beads (8mm)\nDiameter: 7cm\n\nBest Spot\n\nWear on the dominant wrist during daily activities\n\nCare Instruction\n\nAvoid water, perfumes, and store separately after use', '', '', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'dhan-yog-bracelet', 'dhan-yog-bracelet_1.jpg', 'dhan-yog-bracelet_2.jpg', 'dhan-yog-bracelet_3.jpg', 'dhan-yog-bracelet_4.jpg', 'dhan-yog-bracelet_6.jpg', 'dhan-yog-bracelet_8.jpg', 1, '5', '0', 1),
(11, 'Vyapar Vriddhi Yantra', 'vyapar-vriddhi-yantra', 499.00, 499.00, '5,22', 'This Vyapar Vriddhi Yantra is crafted using a sacred metal plate with engraved symbols, traditionally used to support business growth and financial stability. Placing it in your workspace is believed to attract positive energy and better opportunities. It is a simple, powerful tool for those seeking improvement in sales, profits, and overall business flow.\n\n \n\nWho Is This For?\n\nBusiness owners and entrepreneurs\n\nPeople who are running small shops or startups\n\nIndividuals that have been looking for better financial stability\n\nAnyone who wants a meaningful energy tool for work\n\nIdeal Placement\n\nPlace it in the northeast corner of your shop or office\n\nClean it with a soft, dry, and clean cloth\n\nPlace it near your cash counter or work desk\n\nAvoid placing it directly on the floor\n\nMaterial\n\nMetal Sheet Yantra with wooden frame \n\nDimension\n\n3.2 * 3.2 inches\n\nBest Spot\n\nNortheast corner of shop/office\n\nCare Instruction\n\nClean with a dry cloth; keep covered', '', '', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'vyapar-vriddhi-yantra', 'vyapar-vridhi-yantra_1.jpg', 'vyapar-vridhi-yantra_2.jpg', 'vyapar-vridhi-yantra_3.jpg', 'vyapar-vridhi-yantra_4.jpg', 'vyapar-vridhi-yantra_5.jpg', 'vyapar-vridhi-yantra_7.jpg', 1, '5', '0', 1),
(12, 'Gold Plated Rudraksha Chain Bracelet - 6mm', 'gold-plated-rudraksha-chain-bracelet-6mm', 1399.00, 599.00, '7,20,45', 'Enhance your style and spirituality with this Gold Plated Rudraksha Chain Bracelet. Featuring 5 Mukhi Rudraksha beads, it brings positive energy and balance to your life. Lightweight and durable, it’s perfect for daily wear or a spiritual gifting option for your loved ones. A beautiful blend of tradition and elegance.', '', '', 'Return & Exchange Policy: Returns or exchanges must be requested within 7 days of delivery. Products must be unused, undamaged, and in original condition.', 'Disclaimer Images are for reference only. There&#39;s no guarantee of the effectiveness of the product.', 'gold-plated-rudraksha-chain-bracelet-6mm', 'gold-plated-rudraksha-chain-bracelet_1.jpg', 'gold-plated-rudraksha-chain-bracelet_2.jpg', 'gold-plated-rudraksha-chain-bracelet_3.jpg', 'gold-plated-rudraksha-chain-bracelet_6.jpg', 'gold-plated-rudraksha-chain-bracelet_7.jpg', 'gold-plated-rudraksha-chain-bracelet_8.jpg', 1, '5', '0', 1),
